import {DocumentStore,newDocument,validateDocument,screenToWorld,zoomAt,validView} from './core.js';
const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d');
const KEY='maths-workspace:document:v1';let saved,storageError=false,recovery=false;
try{const raw=localStorage.getItem(KEY);if(raw){saved=JSON.parse(raw);if(!validateDocument(saved.document)||!validView(saved.view))throw Error('Invalid save')}}catch{recovery=true;saved=null}
const store=new DocumentStore(saved?.document??newDocument());let view=saved?.view??{x:0,y:0,zoom:1},width=0,height=0,frame=0,timer,space=false,gesture=null;const pointers=new Map();
let theme='light';try{theme=localStorage.getItem('maths-workspace:theme')??(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{}
function applyTheme(){document.body.classList.toggle('dark',theme==='dark');$('theme').setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} mode`);render()}
function save(){clearTimeout(timer);if(recovery){$('save').textContent='Previous save unreadable · changes not saved';return}try{localStorage.setItem(KEY,JSON.stringify({document:store.document,view}));storageError=false;$('save').textContent='Saved on this device'}catch{storageError=true;$('save').textContent='Not saved · browser storage unavailable'}}
function scheduleSave(){$('save').textContent=recovery?'Previous save unreadable · changes not saved':'Saving…';clearTimeout(timer);timer=setTimeout(save,350)}
function draw(){frame=0;const dpr=Math.min(devicePixelRatio||1,3);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);const style=getComputedStyle(document.body);ctx.fillStyle=style.getPropertyValue('--dots');let spacing=24*view.zoom;while(spacing<16)spacing*=5;while(spacing>90)spacing/=5;for(let x=((view.x%spacing)+spacing)%spacing;x<width;x+=spacing)for(let y=((view.y%spacing)+spacing)%spacing;y<height;y+=spacing){ctx.beginPath();ctx.arc(x,y,.75,0,Math.PI*2);ctx.fill()}
// Object renderers are intentionally empty until their corresponding tool milestones.
// Coordinates, document data and selection metadata never depend on canvas pixels.
$('zoomvalue').textContent=`${Math.round(view.zoom*100)}%`;const centre=screenToWorld({x:width/2,y:height/2},view);$('coordinates').textContent=`x ${Math.round(centre.x)}   y ${Math.round(centre.y)}`;}
function render(){if(!frame)frame=requestAnimationFrame(draw)}
function resize(){const rect=canvas.getBoundingClientRect();const old={width,height};width=rect.width;height=rect.height;if(old.width){view.x+=(width-old.width)/2;view.y+=(height-old.height)/2}else if(!saved){view.x=width/2;view.y=height/2}const dpr=Math.min(devicePixelRatio||1,3);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);render()}
new ResizeObserver(resize).observe(canvas);applyTheme();
function sync(){if(document.activeElement!==$('title'))$('title').value=store.document.title;$('undo').disabled=!store.past.length;$('redo').disabled=!store.future.length;$('count').textContent=`${store.document.objects.length} objects`;scheduleSave()}
store.subscribe(sync);$('title').value=store.document.title;if(recovery)$('save').textContent='Previous save unreadable · changes not saved';
$('title').addEventListener('change',()=>{const title=$('title').value.trim()||'Untitled notebook';store.transact(d=>d.title=title);$('title').value=title});$('title').addEventListener('keydown',e=>{if(e.key==='Enter')e.target.blur()});
$('theme').onclick=()=>{theme=theme==='dark'?'light':'dark';applyTheme();try{localStorage.setItem('maths-workspace:theme',theme)}catch{}};
$('undo').onclick=()=>store.undo();$('redo').onclick=()=>store.redo();
function setZoom(factor,p={x:width/2,y:height/2}){view=zoomAt(view,p,factor);render();scheduleSave()}
$('zoomin').onclick=()=>setZoom(1.25);$('zoomout').onclick=()=>setZoom(.8);$('zoomvalue').onclick=()=>setZoom(1/view.zoom);$('home').onclick=()=>{view={x:width/2,y:height/2,zoom:1};render();scheduleSave()};$('hand').onclick=()=>canvas.focus();$('dismiss').onclick=()=>{$('welcome').hidden=true;canvas.focus()};$('help').onclick=()=>$('shortcuts').showModal();$('shortcuts').addEventListener('click',e=>{if(e.target===$('shortcuts'))$('shortcuts').close()});
const point=e=>{const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top}};
function baseline(){const pts=[...pointers.values()];if(pts.length>=2){const [a,b]=pts;gesture={kind:'pinch',view:{...view},centre:{x:(a.x+b.x)/2,y:(a.y+b.y)/2},distance:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y))}}else if(pts.length===1)gesture={kind:'pan',view:{...view},point:pts[0]};else gesture=null}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;e.preventDefault();canvas.focus();canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,point(e));baseline();canvas.classList.add('dragging')});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,point(e));if(!gesture)return;const pts=[...pointers.values()];if(gesture.kind==='pinch'&&pts.length>=2){const [a,b]=pts,centre={x:(a.x+b.x)/2,y:(a.y+b.y)/2};view=zoomAt(gesture.view,gesture.centre,Math.hypot(a.x-b.x,a.y-b.y)/gesture.distance);view.x+=centre.x-gesture.centre.x;view.y+=centre.y-gesture.centre.y}else{view={...gesture.view,x:gesture.view.x+pts[0].x-gesture.point.x,y:gesture.view.y+pts[0].y-gesture.point.y}}render()});
function end(e){if(!pointers.delete(e.pointerId))return;baseline();if(!pointers.size)canvas.classList.remove('dragging');scheduleSave()}
canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',end);
canvas.addEventListener('wheel',e=>{e.preventDefault();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?height:1);setZoom(Math.exp(-Math.max(-300,Math.min(300,delta))*.002),point(e))},{passive:false});
window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA/.test(e.target.tagName)||$('shortcuts').open)return;const mod=e.metaKey||e.ctrlKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?store.redo():store.undo();return}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();store.redo();return}if(mod)return;const steps={ArrowLeft:[60,0],ArrowRight:[-60,0],ArrowUp:[0,60],ArrowDown:[0,-60]};if(steps[e.key]){e.preventDefault();view.x+=steps[e.key][0];view.y+=steps[e.key][1];render();scheduleSave()}if(e.key==='+'||e.key==='='){e.preventDefault();setZoom(1.25)}if(e.key==='-'){e.preventDefault();setZoom(.8)}if(e.key==='0')$('home').click();if(e.key===' '){e.preventDefault();space=true}if(e.key.toLowerCase()==='h')canvas.focus()});window.addEventListener('keyup',e=>{if(e.key===' ')space=false});window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});
if(document.modelContext?.registerTool){for(const tool of [{name:'read_workspace',description:'Read the current notebook title, object count and viewport.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({title:store.document.title,objectCount:store.document.objects.length,view:{...view}})},{name:'rename_notebook',description:'Change the notebook title as one undoable document action.',inputSchema:{type:'object',properties:{title:{type:'string',minLength:1,maxLength:100}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input?.title!=='string'||!input.title.trim()||input.title.length>100)throw Error('A title of 1–100 characters is required');store.transact(d=>d.title=input.title.trim());save();return {title:store.document.title,saved:!storageError&&!recovery}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
